class Database:
    def __init__(self, filename=':memory:', readonly=False, storage_version=None, safe_mode=False):
        self.filename_arg=filename
        self.readonly=readonly
        self.safe_mode=safe_mode
        self.storage_version=storage_version
        self.is_memory = (filename is None or filename=='' or filename==':memory:')
        self.display_name='memory'
        self.filepath=None
        if not self.is_memory:
            self.filepath=filename
            base=os.path.basename(filename.rstrip('/'))
            self.display_name=os.path.splitext(base)[0] or base
        if readonly and self.is_memory:
            raise DuckError("Catalog Error: Cannot launch in-memory database in read-only mode!\n")
        if not self.is_memory:
            fp=self.filepath
            if os.path.isdir(fp):
                raise DuckError(f'IO Error: Could not read from file "{fp}": Is a directory\n')
            if readonly and not os.path.exists(fp):
                raise DuckError(f'IO Error: Cannot open database "{fp}" in read-only mode: database does not exist\n')
            if not os.path.exists(fp):
                parent=os.path.dirname(os.path.abspath(fp))
                if not os.path.isdir(parent):
                    raise DuckError(f'IO Error: Cannot open file "{fp}": No such file or directory\n')
            else:
                if os.path.getsize(fp)==0:
                    raise DuckError(f'IO Error: The file "{fp}" exists, but it is not a valid DuckDB database file!\n')
                with open(fp,'rb') as f: head=f.read(16)
                if not head.startswith(b'SQLite format 3\x00'):
                    raise DuckError(f'IO Error: The file "{fp}" exists, but it is not a valid DuckDB database file!\n')
        # meta
        self.meta={'tables':{},'schemas':['main'],'sequences':{},'macros':{},'types':{},'settings':{},'views_sql':{}}
        self.settings={'threads':os.cpu_count() or 1,'schema':'main','search_path':'','default_null_order':'nulls_last','max_expression_depth':1000}
        self.attached={}  # alias -> filepath/display
        self.current_db=self.display_name
        self.error_pending=None
        self.in_transaction=False
        self.prepared={}
        self.temp_counter=0
        self.virtual_tables={} # sqlite temp name -> cols list
        self.last_result=None
        self.changes_count=0
        # connect
        if self.is_memory:
            self.conn=sqlite3.connect(':memory:', isolation_level=None, check_same_thread=False)
        else:
            uri=None
            self.conn=sqlite3.connect(self.filepath, isolation_level=None, check_same_thread=False)
        self.conn.execute("PRAGMA foreign_keys=ON")
        try: self.conn.execute("PRAGMA journal_mode=DELETE")
        except Exception: pass
        self._register_functions()
        self._init_meta_store()
    def close(self):
        try:
            if self.in_transaction:
                try: self.conn.execute("ROLLBACK")
                except Exception: pass
            self._persist_meta()
            self.conn.close()
        except Exception: pass
    # ----- meta persistence -----
    def _init_meta_store(self):
        # try load
        try:
            if not self.is_memory and not self.readonly:
                self.conn.execute("CREATE TABLE IF NOT EXISTS __duckdb_meta(k TEXT PRIMARY KEY, v TEXT)")
            row=None
            try:
                cur=self.conn.execute("SELECT v FROM __duckdb_meta WHERE k='meta'")
                row=cur.fetchone()
            except Exception: row=None
            if row and row[0]:
                data=json.loads(row[0])
                if isinstance(data,dict): self.meta=data
                for k in ('tables','schemas','sequences','macros','types','settings'):
                    if k not in self.meta: self.meta[k]=[] if k=='schemas' else {}
                if 'main' not in self.meta['schemas']: self.meta['schemas'].insert(0,'main')
