class Database(Database):
    def _special_statement(self, toks, sql):
        first=toks[0].text.upper()
        second=toks[1].text.upper() if len(toks)>1 else ''
        # CREATE etc
        if first=='CREATE': return self._handle_create(toks, sql)
        if first=='DROP': return self._handle_drop(toks, sql)
        if first=='ALTER': return self._handle_alter(toks, sql)
        if first in ('DESCRIBE','DESC'): return self._handle_describe(toks, sql)
        if first=='SHOW': return self._handle_show(toks, sql)
        if first=='PRAGMA': return self._handle_pragma(toks, sql)
        if first=='CALL': return self._handle_call(toks, sql)
        if first=='EXPLAIN': return self._handle_explain(toks, sql)
        if first=='COPY': return self._handle_copy(toks, sql)
        if first in ('EXPORT','IMPORT') and second=='DATABASE': return self._handle_export_import(toks, sql)
        if first=='ATTACH': return self._handle_attach(toks, sql)
        if first=='DETACH': return self._handle_detach(toks, sql)
        if first=='USE':
            # USE db or USE db.schema
            if len(toks)>=2:
                name=unquote_ident(toks[1].text)
                if name.lower() in [self.current_db.lower()] or name.lower() in self.attached or name.lower()=='memory' or name.lower()==self.display_name.lower():
                    if len(toks)>=4 and toks[2].text=='.':
                        sch=unquote_ident(toks[3].text)
                        if sch.lower() in [s.lower() for s in self.meta['schemas']]: self.settings['schema']=sch
                        else: raise DuckError(f'Catalog Error: SET schema: No catalog + schema named "{sch}" found.\n')
                    return None
                raise DuckError(f'Catalog Error: SET schema: No catalog + schema named "{name}" found.\n')
            return None
        if first=='SET':
            return self._handle_set(toks, sql)
        if first=='RESET':
            self.settings['schema']='main'; return None
        if first in ('PREPARE',):
            # PREPARE name AS query
            if len(toks)>=4:
                name=unquote_ident(toks[1].text); 
                # find AS
                rest=sql
                m=re.search(r'\bAS\b',sql,re.I)
                q=sql[m.end():] if m else ''
                self.prepared[name.lower()]={'name':name,'sql':q.strip()}
            return None
        if first=='EXECUTE':
            if len(toks)>=2:
                name=unquote_ident(toks[1].text); prep=self.prepared.get(name.lower())
                if not prep: raise DuckError(f"Catalog Error: Prepared statement with name {name} does not exist!\n")
                q=prep['sql']
                # args
                args=[]
                if len(toks)>2 and toks[2].text=='(':
                    inner=toks[3:-1] if toks[-1].text==')' else toks[3:]
                    for part in split_tok_commas(inner):
                        if part: args.append(tok_text(part))
                # replace $1,$2... and ?
                def repl(m):
                    idx=int(m.group(1)) if m.group(1) else 0
                    return args[idx-1] if 0<idx<=len(args) else m.group(0)
                q2=re.sub(r'\$(\d+)',repl,q)
                q2=re.sub(r'\?', lambda m: args.pop(0) if args else '?', q2, count=10) if '?' in q2 else q2
                return self.execute_sql(q2)
            return None
        if first=='DEALLOCATE':
            if len(toks)>=2: self.prepared.pop(unquote_ident(toks[1].text).lower(),None)
            return None
        if first in ('INSTALL','LOAD'):
            return self._handle_install_load(toks, sql)
        if first=='CHECKPOINT':
