# ---------- Rendering ----------
def escape_duckbox(s):
    mp={'\\':'\\\\','\n':'\\n','\r':'\\r','\t':'\\t','\x00':'\\0','\x07':'\\a','\x08':'\\b','\x0b':'\\v','\x0c':'\\f','\x1b':'\\e'}
    out=[]
    for ch in str(s):
        if ch in mp: out.append(mp[ch])
        elif ord(ch)<32: out.append('\\'+str(ord(ch)))
        else: out.append(ch)
    return ''.join(out)
