    s=format_value(v,col.type if col else None,shell.nullvalue)
    if col and type_category(col.type) not in ('blob',):
        # thousand/decimal separators
        if type_category(col.type) in ('int','double','decimal') and shell.thousand_sep:
            # group integer part
            neg=s.startswith('-'); core=s[1:] if neg else s
            if re.match(r'^\d',core):
