# ---------- Parquet minimal implementation ----------
def _varint_encode(n):
    out=bytearray()
    n=int(n)
    while True:
        b=n & 0x7f; n >>= 7
        if n: out.append(b|0x80)
        else: out.append(b); break
    return bytes(out)
def _zigzag_encode(n, bits=64):
    return (n << 1) ^ (n >> (bits-1))
class _TCWriter:
    def __init__(self): self.buf=bytearray(); self._last_id_stack=[]
    def varint(self,n): self.buf += _varint_encode(n)
    def field(self,ctype,fid,last):
        delta=fid-last
        if 0<delta<=15: self.buf.append((delta<<4)|ctype)
        else:
            self.buf.append(ctype); self.varint(_zigzag_encode(fid,16))
        return fid
    def stop(self): self.buf.append(0)
    def i32_field(self,fid,val,last,ctype=5): # CT_I32=5
        last=self.field(ctype,fid,last); self.varint(_zigzag_encode(int(val),32)); return last
    def i64_field(self,fid,val,last):
        last=self.field(6,fid,last); self.varint(_zigzag_encode(int(val),64)); return last
    def bool_field(self,fid,val,last):
        return self.field(1 if val else 2,fid,last)
    def str_field(self,fid,val,last):
        last=self.field(8,fid,last); b=str(val).encode(); self.varint(len(b)); self.buf+=b; return last
    def list_begin(self,fid,elem_type,size,last):
        last=self.field(9,fid,last)
        if size<15: self.buf.append((size<<4)|elem_type)
        else: self.buf.append(0xf0|elem_type); self.varint(size)
        return last
    def bytes(self): return bytes(self.buf)
def _tc_struct(fn):
    w=_TCWriter(); fn(w); w.stop(); return w.bytes()
def _schema_element_bytes(name, phys=None, converted=None, logical_bytes=None, num_children=None, scale=None, precision=None, rep=1):
    def fn(w):
        last=0
        if phys is not None: last=w.i32_field(1,phys,last)
        if rep is not None: last=w.i32_field(3,rep,last)
        last=w.str_field(4,name,last)
        if num_children is not None: last=w.i32_field(5,num_children,last)
        if converted is not None: last=w.i32_field(6,converted,last)
        if scale is not None: last=w.i32_field(7,scale,last)
        if precision is not None: last=w.i32_field(8,precision,last)
        if logical_bytes is not None:
            last=w.field(12,10,last); w.buf+=logical_bytes
    return _tc_struct(fn)
def _logical_bytes(kind, scale=None, precision=None, bitwidth=None, signed=True):
    # LogicalType union field ids: STRING1, DECIMAL5, DATE6, TIMESTAMP8, INTEGER10
    def fn(w):
        last=0
        if kind=='STRING': last=w.field(12,1,last); w.stop()
        elif kind=='DATE': last=w.field(12,6,last); w.stop()
        elif kind=='DECIMAL':
            last=w.field(12,5,last)
            # DecimalType struct: 1 scale,2 precision
            inner=_TCWriter(); l=0; l=inner.i32_field(1,scale,l); l=inner.i32_field(2,precision,l); inner.stop(); w.buf+=inner.bytes()
        elif kind=='TIMESTAMP':
            last=w.field(12,8,last)
            inner=_TCWriter(); l=0; l=inner.bool_field(1,False,l)
            # unit field 2 struct union MICROS field2
            l=inner.field(12,2,l); u=_TCWriter(); ll=0; ll=u.field(12,2,ll); u.stop(); inner.buf+=u.bytes(); inner.stop(); w.buf+=inner.bytes()
        elif kind=='INTEGER':
            last=w.field(12,10,last)
            inner=_TCWriter(); l=0
            # IntType: 1 bitWidth i8 (compact type BYTE=3), 2 isSigned bool
            l=inner.field(3,1,l); inner.buf.append(int(bitwidth) & 0xff)
            l=inner.bool_field(2,signed,l); inner.stop(); w.buf+=inner.bytes()
    return _tc_struct(fn)
def _page_header_bytes(num_values, data_len):
    def fn(w):
        last=0
        last=w.i32_field(1,0,last) # DATA_PAGE
        last=w.i32_field(2,data_len,last)
        last=w.i32_field(3,data_len,last)
        # data_page_header field5 struct
        last=w.field(12,5,last)
        inner=_TCWriter(); l=0; l=inner.i32_field(1,num_values,l); l=inner.i32_field(2,0,l); l=inner.i32_field(3,3,l); l=inner.i32_field(4,3,l); inner.stop(); w.buf+=inner.bytes()
    return _tc_struct(fn)
def _encode_def_levels(levels):
    if not levels: return b''
    # RLE runs
    out=bytearray(); i=0
    while i<len(levels):
        j=i
        while j<len(levels) and levels[j]==levels[i]: j+=1
        run=j-i; out+=_varint_encode(run<<1); out.append(levels[i] & 0xff); i=j
    return struct.pack('<I',len(out))+bytes(out)
def _plain_encode(coltype, vals):
    up=str(coltype).upper(); cat=type_category(coltype); out=bytearray()
    for v in vals:
        if cat=='bool': pass
        elif up=='BOOLEAN': pass
        elif up in ('DATE',): 
            d=datetime.date.fromisoformat(str(v)[:10]); out+=struct.pack('<i',(d-datetime.date(1970,1,1)).days)
        elif up.startswith('DECIMAL'):
            sc=decimal_scale(coltype); iv=int((Decimal(str(v))* (10**sc)).to_integral_value()); out+=struct.pack('<i',iv)
        elif cat=='int':
            if up in ('BIGINT','HUGEINT'): out+=struct.pack('<q',int(v))
            else: out+=struct.pack('<i',int(v))
        elif up=='FLOAT': out+=struct.pack('<f',float(v))
        elif up=='DOUBLE': out+=struct.pack('<d',float(v))
        elif up in ('TIMESTAMP','TIMESTAMP WITH TIME ZONE'):
            dt=parse_date_value(v); us=int(dt.replace(tzinfo=datetime.timezone.utc).timestamp()*1000000) if dt else 0; out+=struct.pack('<q',us)
        elif isinstance(v,bytes): out+=struct.pack('<I',len(v)); out+=v
        else: b=str(v).encode(); out+=struct.pack('<I',len(b)); out+=b
    if up=='BOOLEAN' or cat=='bool':
        # bit pack
        by=bytearray((len(vals)+7)//8)
        for i,v in enumerate(vals):
            if v: by[i//8] |= (1 << (i%8))
        out=by
    return bytes(out)
def _parquet_write(path,res):
    cols=res.cols; rows=res.rows
    # map column to physical
    def phys_info(t):
        up=str(t).upper(); cat=type_category(t)
        if up=='BOOLEAN' or cat=='bool': return (0,None,_logical_bytes('STRING') if False else None)
        if up=='DATE': return (1,7,_logical_bytes('DATE')) # converted DATE=7? format enum DATE 7
        if up.startswith('DECIMAL'):
            m=re.match(r'DECIMAL\((\d+),(\d+)\)',up); prec=int(m.group(1)) if m else 18; sc=int(m.group(2)) if m else 3
            return (1,6,_logical_bytes('DECIMAL',sc,prec))
        if cat=='int':
            if up in ('BIGINT','HUGEINT'): return (2,16,_logical_bytes('INTEGER',bitwidth=64,signed=True))
            bw=8 if up=='TINYINT' else 16 if up=='SMALLINT' else 32
            conv=13 if up=='TINYINT' else 14 if up=='SMALLINT' else 15
            return (1,conv,_logical_bytes('INTEGER',bitwidth=bw,signed=True))
        if up=='FLOAT': return (4,None,None)
        if up=='DOUBLE': return (5,None,None)
        if up in ('TIMESTAMP','TIMESTAMP WITH TIME ZONE'): return (2,11,_logical_bytes('TIMESTAMP'))
        if cat=='blob': return (6,None,None)
        return (6,0,_logical_bytes('STRING')) # converted UTF8=0? actually 1? We'll use logical string
    data=bytearray(b'PAR1')
    col_chunks=[]
    for ci,c in enumerate(cols):
        vals=[r[ci] for r in rows]
        levels=[0 if v is None else 1 for v in vals]
        nonnull=[v for v in vals if v is not None]
        page_data=_encode_def_levels(levels)+_plain_encode(c.type,nonnull)
        header=_page_header_bytes(len(vals),len(page_data))
        offset=len(data); data+=header+page_data
        phys,conv,logical=phys_info(c.type)
        col_chunks.append((c,phys,conv,offset,len(header)+len(page_data),len(vals)))
    # schema
    schema_bytes=[]
    schema_bytes.append(_schema_element_bytes('duckdb_schema',phys=None,converted=None,num_children=len(cols),rep=None))
    for c in cols:
        phys,conv,logical=phys_info(c.type)
        # converted enum correction: UTF8=1, DATE=7, DECIMAL=6, INT_8=13 etc already
        if str(c.type).upper()=='VARCHAR': conv=1
        if str(c.type).upper() in ('TIMESTAMP','TIMESTAMP WITH TIME ZONE'): conv=None
        sc=decimal_scale(c.type) if str(c.type).upper().startswith('DECIMAL') else None
        prec=None
        if sc is not None:
            mm=re.match(r'DECIMAL\((\d+),',str(c.type).upper()); prec=int(mm.group(1)) if mm else 18
        schema_bytes.append(_schema_element_bytes(c.name,phys=phys,converted=conv,logical_bytes=logical,scale=sc,precision=prec,rep=1))
    # row group
    def chunk_fn(c,phys,conv,offset,total,numvals):
        def fn(w):
            last=0
            last=w.i64_field(2,offset,last)
            last=w.field(12,3,last)
            # ColumnMetaData
            inner=_TCWriter(); l=0
            l=inner.i32_field(1,phys,l)
            # encodings list field2 [PLAIN0,RLE3]
            l=inner.list_begin(2,5,2,l); inner.varint(_zigzag_encode(0,32)); inner.varint(_zigzag_encode(3,32))
            # path field3 list string
            l=inner.list_begin(3,8,1,l); b=c.name.encode(); inner.varint(len(b)); inner.buf+=b
            l=inner.i32_field(4,0,l) # codec uncompressed
            l=inner.i64_field(5,numvals,l); l=inner.i64_field(6,total,l); l=inner.i64_field(7,total,l)
            l=inner.i64_field(12,offset,l)
